# ruff: noqa: I001, E401, E402, E701, E702, E731, F401, F811
# fmt: off
from __future__ import annotations; from collections.abc import Sequence; from dataclasses import dataclass; from typing import Any; from psycopg import Connection
@dataclass(frozen=True)
class Invariant: id: str; statement: str; self_evident_because: str; sql: str; sample_sql: str | None = None
@dataclass(frozen=True)
class InvariantResult:
    invariant: Invariant; violations: int; samples: tuple[str, ...] = ()
    @property
    def ok(self) -> bool: return self.violations == 0
INVARIANTS: tuple[Invariant, ...] = ( Invariant( id="I1", statement="A normalized financial fact never reports gross profit above revenue", self_evident_because=( "gross profit is revenue minus cost of revenue, so it cannot exceed revenue for any issuer " "in any industry under any accounting standard" ), sql="select count(*) from staging.capture_observation_payloads where normalized_payload->>'gross_profit'is not null and normalized_payload->>'revenue'is not null and (normalized_payload->>'gross_profit')::numeric > (normalized_payload->>'revenue')::numeric", sample_sql="select distinct o.subject_id ||': gross_profit='|| (p.normalized_payload->>'gross_profit') ||' > revenue='|| (p.normalized_payload->>'revenue') from staging.capture_observation_payloads p join staging.capture_normalized_observations o using (observation_id) where (p.normalized_payload->>'gross_profit')::numeric > (p.normalized_payload->>'revenue')::numeric limit 10", ), Invariant( id="I2", statement="Every raw.fetches row points into the configured raw object bucket", self_evident_because=( "a pointer row whose bucket does not exist cannot be dereferenced, so the bytes it claims " "to describe are unreachable no matter what the row says" ), sql="select count(*) from raw.fetches where object_uri not like 's3://truealpha-raw/%%'", sample_sql="select distinct object_uri from raw.fetches where object_uri not like 's3://truealpha-raw/%%' limit 5", ), Invariant( id="I3", statement="A JSON source response is never 1 byte or fewer", self_evident_because="the shortest syntactically valid JSON document is 2 bytes ('{}')", sql="select count(*) from raw.fetches where content_type = 'application/json' and byte_length <= 1", sample_sql=( "select source ||':'|| source_record_id ||' byte_length='|| byte_length from raw.fetches where content_type ='application/json'and byte_length <= 1 limit 5" ), ), Invariant( id="I4", statement="A captured market price carries at most 4 decimal places", self_evident_because=( "no exchange quotes a US equity beyond four decimals, so extra digits are an artifact " "introduced after the vendor's response, not price information" ), sql="select count(*) from staging.capture_observation_payloads where normalized_payload->>'close'is not null and length(split_part(normalized_payload->>'close','.', 2)) > 4", sample_sql="select distinct normalized_payload->>'close'from staging.capture_observation_payloads where normalized_payload->>'close'is not null and length(split_part(normalized_payload->>'close','.', 2)) > 4 limit 5", ), Invariant( id="I5", statement="Shares outstanding, when asserted, is positive", self_evident_because="a listed issuer with zero or negative shares outstanding is not a listed issuer", sql="select count(*) from staging.capture_observation_payloads where normalized_payload->>'shares_outstanding'is not null and (normalized_payload->>'shares_outstanding')::numeric <= 0", ), Invariant( id="I6", statement="The governed current pointer resolves to a run that has mart results", self_evident_because=( "a head pointer with nothing behind it makes every consumer read fail, independently of " "whether the numbers behind it are right" ), sql="select count(*) from mart.current_pointer_head h where not exists (select 1 from mart.topt_core_results r where r.run_id = h.target_run_id)", sample_sql=("select universe_id, target_run_id from mart.current_pointer_head order by universe_id limit 5"), ), )
def check(connection: Connection[Any], invariants: Sequence[Invariant] = INVARIANTS) -> tuple[InvariantResult, ...]:
    results: list[InvariantResult] = []
    for invariant in invariants:
        row = connection.execute(invariant.sql).fetchone(); violations = int(row[0]) if row is not None else 0; samples: tuple[str, ...] = ()
        if violations and invariant.sample_sql: samples = tuple(str(item[0]) for item in connection.execute(invariant.sample_sql).fetchall())
        results.append(InvariantResult(invariant=invariant, violations=violations, samples=samples))
    return tuple(results)
